INSERT INTO `lessons` (`id`, `section_id`, `title_ru`, `slug`, `lesson_order`, `content`) VALUES
(2, 1, '1.1. Знакомство с Google Таблицами, датасетом и интерфейсом', 'google-sheets-intro', 1, '{\"lab\": \"<p>Изучите листы учебного датасета.</p><p>По очереди откройте три листа:</p><p>Клиенты</p><p>Меню и Товары</p><p>Заказы</p><p>Для каждого листа определите, какую информацию он содержит.</p><p>На листе «Клиенты» найдите:</p><p>ID клиента;</p><p>ФИО;</p><p>адрес доставки;</p><p>статус;</p><p>дату регистрации.</p><p>На листе «Меню и Товары» найдите:</p><p>ID товара;</p><p>название товара;</p><p>категорию;</p><p>себестоимость;</p><p>цену продажи.</p><p>На листе «Заказы» найдите:</p><p>ID заказа;</p><p>ID клиента;</p><p>ID товара;</p><p>количество;</p><p>сумму заказа;</p><p>канал поступления;</p><p>статус оплаты;</p><p>статус заказа;</p><p>курьера;</p><p>дату заказа.</p>\", \"tests\": [{\"answers\": [\"Можно работать без подключения к интернету  \", \"Файл автоматически превращается в презентацию\", \"Несколько пользователей могут работать с одним документом при наличии доступа ✓\", \"Каждый пользователь обязан создавать отдельный файл\"], \"correct\": 0, \"question\": \"Какое главное преимущество Google Таблиц особенно важно при совместной работе?\"}, {\"answers\": [\"В облаке Google Диска и документ обновляется автоматически ✓  \", \"В оперативной памяти компьютера до закрытия браузера\", \"В отдельном текстовом файле на рабочем столе\", \"На флеш-накопителе пользователя\"], \"correct\": 0, \"question\": \"Где хранятся изменения в обычной работе с Google Таблицами?\"}, {\"answers\": [\"Второй столбец и строку D  \", \"Столбец D и вторую строку ✓\", \"Четвёртый лист и вторую запись\", \"Диапазон от D до 2\"], \"correct\": 0, \"question\": \"Что обозначает адрес ячейки D2?\"}, {\"answers\": [\"#  \", \"$\", \"= ✓\", \"@\"], \"correct\": 0, \"question\": \"С какого символа должна начинаться формула в Google Таблицах?\"}, {\"answers\": [\"•  \", \"˟\", \"×\", \"*✓\"], \"correct\": 0, \"question\": \"Какой оператор используется для умножения в формуле?\"}, {\"answers\": [\"Название товара  \", \"Цена товара\", \"Количество товара из ячейки D2 ✓\", \"Номер листа\"], \"correct\": 0, \"question\": \"Что означает D2 в формуле =D2*3100?\"}, {\"answers\": [\"Чтобы изменения исходного учебного файла были видны всем студентам  \", \"Чтобы работать со своими данными, не изменяя исходный учебный файл ✓\", \"Чтобы удалить все остальные листы\", \"Чтобы отключить автоматическое сохранение Google Таблиц\"], \"correct\": 0, \"question\": \"Почему студенту нужно создать собственную копию учебного датасета?\"}], \"theory\": \"<p>Google Таблицы — это облачный табличный процессор. Он позволяет хранить рабочие данные в интернете, открывать их с разных устройств и совместно работать с ними. В этом курсе Google Таблицы будут использоваться как простая облачная база данных для службы доставки еды.</p><p>В следующих уроках на этих же данных мы будем рассчитывать показатели продаж, связывать информацию между листами, строить сводные таблицы и создавать диаграммы. Поэтому сейчас главная задача — научиться уверенно работать с файлом и понимать, где находятся нужные данные.</p><p>&nbsp;</p><p><strong>Google&nbsp;Таблицы и Microsoft&nbsp;Excel</strong></p><p>Если вы раньше работали с Microsoft Excel, интерфейс Google Таблиц покажется знакомым. В обоих инструментах есть строки, столбцы, ячейки, листы и формулы.</p><p>Главное отличие связано с местом хранения и способом совместной работы.</p><p>Microsoft Excel обычно используется как программа на компьютере. Файл можно сохранить на компьютере, отправить другому человеку или разместить в облачном хранилище.</p><p>Google Таблицы изначально работают в браузере и сохраняют документ в Google Диске. Благодаря этому изменения обычно сохраняются автоматически. Не нужно постоянно нажимать кнопку «Сохранить».</p><p>Ещё одно важное преимущество — совместный доступ. Один файл можно открыть нескольким пользователям и работать с ним совместно, если владелец предоставил соответствующие права доступа.</p><p>Для бизнеса это удобно, например, когда один сотрудник заносит заказы, другой проверяет оплату, а руководитель просматривает показатели.</p><p>В этом курсе мы будем использовать именно облачный подход: каждый студент получит готовый учебный файл и сделает его собственную копию в своём Google Диске.</p><p>&nbsp;</p><p><strong>Учебный датасет службы доставки</strong></p><p>Для практических занятий подготовлен единый датасет службы доставки еды.&nbsp;</p><p>Он содержит данные, похожие на те, которые могут использоваться небольшим бизнесом в ежедневной работе.</p><p>Готовый датасет доступен в облаке.</p><p>Важно: работать нужно не с исходным учебным файлом, а со своей копией.</p><p>&nbsp;</p><p><strong>Как сделать копию учебного датасета</strong></p><p>Войдите в свой Google аккаунт.</p><p>(В конце пары не забудьте выйти из своего Google аккаунта.)</p><p>Откройте учебный датасет по адресу:</p><p><a href=\\\"https://docs.google.com/spreadsheets/d/1lZAOKx9pjVMnFsK8Qc57382igG85OxQVbqTvTG0i7oE/edit?usp=sharing\\\">https://docs.google.com/spreadsheets/d/1lZAOKx9pjVMnFsK8Qc57382igG85OxQVbqTvTG0i7oE/edit?usp=sharing</a></p><p>&nbsp;</p><p>Вам нужна собственная копия файла, потому что исходный документ является готовым учебным датасетом. Изменения в своей копии не будут мешать другим студентам.</p><p>После открытия файла найдите команду создания копии документа в меню Google Таблиц.</p><p>Создайте копию.</p><p>Переименуйте копию файла с названия \\\"Копия Сервис доставки - Копия\\\"</p><p>на \\\"Сервис доставки - &lt;ваше Фамилия Имя&gt;\\\"</p><p>Сохраните копию на своём Google Диске.</p><p>После копирования проверьте, что работаете именно с копией, а не с исходным файлом.</p><p>Удобно дать копии понятное название, например:</p><p>&nbsp;</p><p><strong>Описание учебного датасета</strong></p><p>В учебном датасете три листа:</p><p>«Клиенты» — сведения о клиентах;</p><p>«Меню и Товары» — сведения о товарах меню и ценах;</p><p>«Заказы» — сведения о заказах.</p><p>&nbsp;</p><p>Лист «Клиенты»</p><p>На этом листе находятся сведения о клиентах.</p><p>В учебном датасете используются столбцы:</p><p>ID_Клиента — уникальный идентификатор клиента;</p><p>ФИО — имя клиента;</p><p>Телефон — контактный номер;</p><p>Адрес_Доставки — адрес доставки;</p><p>Статус — например, статус постоянного клиента;</p><p>Дата_Регистрации — дата регистрации клиента.</p><p>ID нужен для однозначного определения конкретной записи. Например, CUST-001 — это не имя человека, а уникальный идентификатор записи клиента.</p><p>&nbsp;</p><p>Лист «Меню и Товары»</p><p>Этот лист содержит информацию о товарах.</p><p>В нём есть:</p><p>ID_Товара — уникальный идентификатор товара;</p><p>Наименование — название блюда или другого товара;</p><p>Категория — категория товара;</p><p>Себестоимость_Тг — себестоимость;</p><p>Цена_Продажи_Тг — цена, по которой товар продаётся клиенту.</p><p>Например, для каждого товара можно отдельно увидеть его себестоимость и цену продажи.</p><p>Эти данные понадобятся в следующих уроках, когда мы будем анализировать продажи и связывать информацию между листами.</p><p>&nbsp;</p><p>Лист «Заказы»</p><p>Это основной рабочий лист для анализа заказов.</p><p>В учебном датасете он содержит 100 записей и следующие столбцы:</p><p>ID_Заказа — идентификатор заказа;</p><p>ID_Клиента — идентификатор клиента;</p><p>ID_Товара — идентификатор товара;</p><p>Количество — количество единиц товара в заказе;</p><p>Сумма_Заказа_Тг — сумма заказа;</p><p>Канал_Поступления — откуда поступил заказ;</p><p>Статус_Оплаты — состояние оплаты;</p><p>Статус_Заказа — состояние выполнения заказа;</p><p>Курьер — назначенный курьер;</p><p>Дата_Заказа — дата и время заказа.</p><p>Обратите внимание: одна строка таблицы соответствует одной записи о заказе.</p><p>Например, в первой строке данных находится заказ ORD-001. Для него указаны клиент CUST-016, товар PROD-009, количество 2 и сумма заказа 6200 тенге.</p><p>&nbsp;</p><p><strong>Основные элементы интерфейса&nbsp;Google&nbsp;таблиц</strong></p><p>Обратите внимание на основные части интерфейса.</p><p>В верхней части находится название документа.&nbsp;</p><p>Ниже расположено основное меню с командами работы с таблицей.</p><p>Под меню находится панель инструментов. На ней расположены часто используемые команды форматирования и работы с данными.</p><p>Центральную часть экрана занимает рабочая область с ячейками.</p><p>Слева находятся номера строк, а сверху — обозначения столбцов.</p><p>В нижней части окна расположены вкладки листов. Именно здесь можно переключаться между «Клиенты», «Меню и Товары» и «Заказы».</p><p>&nbsp;</p><p>Автоматическое сохранение</p><p>В Google Таблицах изменения сохраняются в облаке автоматически.</p><p>Это отличается от привычной работы с локальным файлом Excel, где пользователь может вручную сохранять документ.</p><p>Несмотря на автоматическое сохранение, полезно следить за тем, что изменения действительно записались. Особенно это важно при нестабильном интернет-соединении.</p><p>Главное правило лабораторной работы: после выполнения задания не закрывайте таблицу сразу. Убедитесь, что изменения сохранились.</p><p>&nbsp;</p><p><strong>Ячейка, строка и столбец</strong></p><p>Основной элемент Google Таблиц — ячейка.</p><p>Ячейка находится на пересечении столбца и строки. У каждой ячейки есть адрес.</p><p>Например:</p><p>A1</p><p>означает:</p><p>A — столбец A;</p><p>1 — первая строка.</p><p>Если выбрать ячейку D2, это означает столбец D и строку 2.</p><p>Столбцы обозначаются буквами: A, B, C, D и далее.</p><p>Строки обозначаются числами: 1, 2, 3, 4 и далее.</p><p>Первая строка учебной таблицы обычно содержит названия столбцов. Поэтому первая запись данных начинается со второй строки.</p><p>&nbsp;</p><p>Например, на листе «Заказы»:</p><p>D1 содержит название столбца Количество.</p><p>А значение количества в первой записи находится в D2.</p><p>Это правило адресации понадобится нам при работе с формулами.</p><p>&nbsp;</p><p>При выборе ячейки вокруг неё появляется рамка. Это означает, что ячейка активна и готова для ввода или редактирования данных.</p><p>Если нужно изменить значение ячейки, её можно выбрать и начать вводить новое значение.</p><p>&nbsp;</p><p><strong>Первая простая формула</strong></p><p>Формула в Google Таблицах начинается со знака =.</p><p>Например:</p><p>=2+3</p><p>после ввода даст результат 5.</p><p>Но для бизнес-задач интереснее использовать значения из ячеек.</p><p>На листе «Заказы» в первой записи:</p><p>количество находится в D2;</p><p>сумма заказа уже указана в E2.</p><p>Чтобы потренироваться с формулами, добавим рядом с таблицей временный расчёт.</p><p>В первой строке заказа количество равно 2. Для товара PROD-009 на листе «Меню и Товары» цена продажи составляет 3100 тенге.</p><p>Поэтому итоговую стоимость можно рассчитать так:</p><p>=D2*3100</p><p>Результат будет равен 6200.</p><p>Здесь D2 — количество товара, а 3100 — цена одной единицы товара.</p><p>Знак * означает умножение.</p><p>В дальнейшем мы научимся автоматически получать цену товара из листа меню с помощью функции XLOOKUP.&nbsp;</p><p>Сейчас этого делать не нужно - функция XLOOKUP будет изучаться в уроке 1.3.</p><p>На этом этапе важно понять только базовый принцип:</p><p>= сообщает Google Таблицам, что начинается формула;</p><p>D2 позволяет использовать значение из ячейки;</p><p>* выполняет умножение.</p><p>Формула не является обычным текстом. Google Таблицы вычисляют её и показывают полученный результат.</p><p>Если изменить количество товара, результат формулы, использующей ячейку D2, также изменится автоматически.</p><p>&nbsp;</p><p>Что нужно запомнить</p><p>Google Таблицы — облачный инструмент для работы с табличными данными.</p><p>В нашем курсе таблица используется как простая база данных службы доставки.</p><p>Учебный файл содержит три листа: «Клиенты», «Меню и Товары» и «Заказы».</p><p>Каждый лист предназначен для своего типа информации.</p><p>Ячейка определяется буквой столбца и номером строки, например D2.</p><p>Формула начинается со знака =.</p><p>Для умножения используется знак *.</p><p>Исходный учебный файл нужно сначала скопировать на свой Google Диск, после чего выполнять практические задания в своей копии.</p>\"}'),
(3, 1, '1.2. Формулы и функции для бизнес-анализа продаж', 'formulas-and-functions', 2, '{\"lab\": \"<p>В этой лабораторной работе не будут повторяться расчёты, разобранные в теоретической части.&nbsp;</p><p>Ваша задача — самостоятельно выбрать подходящую функцию из изученных SUM, AVERAGE, COUNTIF, MIN, MAX и SUMIF, определить нужный диапазон и получить ответ на бизнес-вопрос.</p><p>Для части заданий используйте лист Заказы, а для части — лист Меню и Товары.&nbsp;</p><p>&nbsp;</p><p>Задача 1. Анализ каналов поступления заказов</p><p>Руководитель хочет понять, через какие каналы чаще всего поступают заказы.</p><p>Используя лист Заказы, определите количество заказов, поступивших через:</p><p>WhatsApp;</p><p>Telegram-бот;</p><p>Звонок;</p><p>Приложение/Сайт.</p><p>Самостоятельно определите, какую функцию использовать и в каком столбце искать условие.</p><p>В конце укажите, какой канал оказался самым распространённым.</p><p>&nbsp;</p><p>Задача 2. Сравнение продаж по каналам</p><p>Теперь руководителю нужно сравнить не количество заказов, а их денежный объём.</p><p>Для каждого из четырёх каналов из предыдущей задачи определите общую сумму заказов.</p><p>Используйте ту же логику анализа, но самостоятельно выберите функцию, которая позволяет суммировать значения только для записей, соответствующих заданному условию.</p><p>Сравните результаты и определите канал с наибольшей суммой заказов.</p><p>&nbsp;</p><p>Задача 3. Анализ работы курьеров</p><p>Определите количество заказов, которые были назначены каждому из курьеров:</p><p>Алихан (Курьер #1);</p><p>Дмитрий (Курьер #2);</p><p>Руслан (Курьер #3);</p><p>Ерлан (Курьер #4).</p><p>После расчёта определите, у какого курьера больше всего заказов.</p><p>Обратите внимание, что в таблице встречаются отменённые заказы без назначенного курьера. Не включайте их в результаты для конкретных курьеров.</p><p>&nbsp;</p><p>Задача 4. Средняя стоимость товаров в категории</p><p>Перейдите к листу Меню и Товары.</p><p>Для категории Пицца определите среднюю цену продажи товаров.</p><p>Затем выполните такой же расчёт для категории Суши и Роллы.</p><p>Сравните два результата и определите, в какой из этих категорий средняя цена продажи выше.</p><p>Здесь вам потребуется самостоятельно определить, как применить изученную функцию среднего значения к данным, отобранным по условию.</p><p>&nbsp;</p><p>Задача 5. Размер ассортимента по категориям</p><p>На листе Меню и Товары определите, сколько товаров относится к каждой из следующих категорий:</p><p>Пицца;</p><p>Суши и Роллы;</p><p>Бургеры;</p><p>Напитки.</p><p>После расчёта определите категорию с наибольшим количеством позиций.</p><p>&nbsp;</p><p>Задача 6. Анализ ценового диапазона</p><p>На листе Меню и Товары найдите:</p><p>самую низкую себестоимость товара;</p><p>самую высокую цену продажи.</p><p>Насколько отличается самая высокая цена продажи от самой низкой?</p><p>&nbsp;</p><p>Задача 7. Анализ количества проданных единиц</p><p>В листе Заказы есть столбец Количество.</p><p>Определите:</p><p>общее количество единиц товаров во всех заказах;</p><p>среднее количество единиц товара в одном заказе;</p><p>максимальное количество единиц товара в одном заказе.</p><p>Для каждого показателя самостоятельно выберите подходящую изученную функцию.</p><p>Обратите внимание: здесь анализируется не денежная сумма заказа, а количество товаров.</p><p>&nbsp;</p><p>Задача 8. Анализ ассортимента по себестоимости</p><p>На листе Меню и Товары определите, сколько товаров имеют себестоимость ниже 1000 тг.</p><p>Затем определите, сколько товаров имеют цену продажи выше 3000 тг.</p><p>Для решения самостоятельно определите:</p><p>какой столбец нужно анализировать;</p><p>какое условие использовать;</p><p>какую функцию применить.</p><p>&nbsp;</p><p>Задача 9. Мини-отчёт руководителю</p><p>На основании выполненных расчётов подготовьте небольшой набор показателей для руководителя службы доставки.</p><p>Самостоятельно выберите и рассчитайте:</p><p>канал, через который поступает больше всего заказов;</p><p>канал с наибольшей суммой заказов;</p><p>курьера с наибольшим количеством назначенных заказов;</p><p>максимальную цену продажи товара;</p><p>среднюю цену продажи пиццы.</p><p>Рядом с каждым показателем укажите полученное значение.</p><p>В конце сформулируйте 2–3 предложения с выводами о продажах и ассортименте.</p><p>&nbsp;</p><p>Главная цель лабораторной работы — не получить конкретный набор чисел, а научиться самостоятельно переводить бизнес-вопрос в последовательность действий: определить показатель, найти нужный столбец, выбрать подходящую функцию, указать условие и проверить полученный результат.</p>\", \"tests\": [{\"answers\": [\":\", \"= ✓\", \":=\", \"==\"], \"correct\": null, \"question\": \"Какой символ должен стоять в начале формулы Google Таблиц?\"}, {\"answers\": [\"Считает количество строк с данными\", \"Находит сумму всех чисел в таблице\", \"Складывает значения выбранного диапазона ✓\", \"Преобразует текст в сумму\"], \"correct\": null, \"question\": \"Что делает функция SUM?\"}, {\"answers\": [\"MIDDLE\", \"COUNTIF\", \"SUMIF\", \"AVERAGE ✓\"], \"correct\": null, \"question\": \"Какая функция используется для расчёта среднего значения?\"}, {\"answers\": [\"Считает ячейки, соответствующие условию ✓\", \"Складывает все числа в таблице\", \"Находит самый большой заказ\", \"Удаляет строки, которые не соответствуют условию\"], \"correct\": null, \"question\": \"Какую задачу решает COUNTIF?\"}, {\"answers\": [\"Находит наименьшее значение в таблице\", \"Находит наименьшее значение в диапазоне ✓\", \"Считает количество заказов\", \"Складывает значения в столбце E\"], \"correct\": null, \"question\": \"Что делает формула =MIN(E2:E101)?\"}, {\"answers\": [\"AVERAGE\", \"COUNTIF\", \"IFSUM\", \"SUMIF ✓\"], \"correct\": null, \"question\": \"Какая функция нужна, чтобы получить сумму только тех заказов, которые соответствуют определённому условию?\"}, {\"answers\": [\"Диапазон, в котором находятся суммы заказов\", \"Диапазон, в котором проверяется условие ✓\", \"Диапазон клиентов Kaspi\", \"Диапазон с датами регистрации клиентов\"], \"correct\": null, \"question\": \"В формуле =SUMIF(G2:G101,\\\"Оплачено Kaspi\\\",E2:E101) что означает диапазон G2:G101?\"}, {\"answers\": [\"Складывает суммы заказов Kaspi\", \"Находит самый дорогой заказ\", \"Считает количество заказов с указанным способом оплаты ✓\", \"Рассчитывает средний чек Kaspi\"], \"correct\": null, \"question\": \"Что делает формула =COUNTIF(G2:G101,\\\"Оплачено Kaspi\\\")?\"}, {\"answers\": [\"Среднюю сумму заказа ✓\", \"Количество заказов\", \"Самую маленькую сумму заказа\", \"Общую сумму всех заказов в диапазоне\"], \"correct\": null, \"question\": \"Какой показатель можно получить с помощью =AVERAGE(E2:E101)?\"}], \"theory\": \"<p>После первого урока у вас уже есть копия учебной таблицы службы доставки и вы умеете работать с листом «Заказы». Теперь начнём использовать Google Таблицы не просто для хранения данных, а для получения ответов на бизнес-вопросы.</p><p>Например:</p><p>сколько денег принесли все заказы;</p><p>какой средний чек;</p><p>сколько было заказов;</p><p>какой заказ был самым крупным;</p><p>какая сумма продаж приходится на определённый способ оплаты;</p><p>сколько заказов относится к выбранному условию.</p><p>&nbsp;</p><p>В учебном датасете лист «Заказы» содержит 100 заказов и, среди прочего, следующие поля: ID_Заказа, Количество, Сумма_Заказа_Тг, Статус_Оплаты, Статус_Заказа, Курьер, Дата_Заказа. Эти данные будем использовать для расчётов.</p><p>&nbsp;</p><p>В этом уроке мы изучим функции SUM, AVERAGE, COUNTIF, MIN, MAX&nbsp;и SUMIF.</p><p>&nbsp;</p><p><strong>Формулы и функции</strong></p><p>Формулы и функции для этого урока можете писать в любой свободной ячейке справа от имеющихся данных датасета.</p><p>Формула в Google Таблицах начинается со знака =.</p><p>Например:</p><p><code>=2+3</code></p><p>После нажатия Enter таблица покажет результат 5.</p><p>Но в бизнес-таблицах редко приходится складывать несколько чисел вручную. Обычно нужно обработать целый диапазон ячеек. Для этого используются функции.</p><p>Функция — это готовая команда, которая выполняет определённое действие над данными.</p><p>Общий вид функции:</p><p><code>=НАЗВАНИЕ_ФУНКЦИИ(аргумент)</code></p><p>Аргумент — это данные, которые функция должна обработать.</p><p>Например:</p><p><code>=SUM(E2:E101)</code></p><p>Здесь:</p><p>SUM — название функции;</p><p>E2:E101 — диапазон ячеек;</p><p>E2:E101 означает все ячейки от E2 до E101;</p><p>результатом будет сумма всех значений в этом диапазоне.</p><p>&nbsp;</p><p>В нашем датасете столбец Сумма_Заказа_Тг находится в столбце E листа «Заказы». Поэтому диапазон E2:E101 содержит суммы 100 заказов.</p><p>Важно: диапазон нужно выбирать по фактическому расположению данных. Если в вашей копии таблицы строки или столбцы расположены иначе, ориентируйтесь на заголовки.</p><p>В зависимости от региональных настроек Google Таблиц аргументы функции могут разделяться запятой или точкой с запятой.&nbsp;</p><p>Например:</p><p><code>=SUM(E2:E101)</code></p><p>Функция с несколькими аргументами может выглядеть так:</p><p><code>=SUMIF(G2:G101,\\\"Оплачено Kaspi\\\",E2:E101)</code></p><p>Если ваша таблица требует точку с запятой, используйте:</p><p><code>=SUMIF(G2:G101;\\\"Оплачено Kaspi\\\";E2:E101)</code></p><p>Смысл функции при этом не меняется.</p><p>&nbsp;</p><p><strong>SUM — общая сумма</strong></p><p>SUM используется, когда нужно сложить значения.</p><p>Для расчёта общей суммы заказов:</p><p><code>=SUM(E2:E101)</code></p><p>В учебном датасете результат составляет 404 550 тг.</p><p>Такой расчёт отвечает на простой вопрос: «Какова сумма всех значений в выбранном столбце?»</p><p>SUM можно применять не только к продажам.&nbsp;</p><p>Например, с её помощью можно сложить количество товаров, расходы, количество часов и другие числовые показатели.</p><p>Главное правило: в качестве диапазона выбирайте именно тот столбец, показатель которого хотите суммировать.</p><p>&nbsp;</p><p><strong>AVERAGE — среднее значение</strong></p><p>AVERAGE рассчитывает среднее арифметическое.</p><p>Для суммы заказов:</p><p><code>=AVERAGE(E2:E101)</code></p><p>В учебном датасете средняя сумма заказа составляет 4 045,50 тг.</p><p>Средний чек помогает оценить типичный размер заказа. Если общее количество заказов увеличилось, но средний чек уменьшился, бизнес получает другую картину, чем при одновременном росте количества заказов и среднего чека.</p><p>Важно понимать разницу:</p><p>SUM отвечает на вопрос «сколько всего?».</p><p>AVERAGE отвечает на вопрос «сколько в среднем на один показатель?».</p><p>Не нужно складывать значения вручную и затем самостоятельно делить на количество строк. AVERAGE делает это автоматически.</p><p>&nbsp;</p><p><strong>COUNTIF — подсчёт по условию</strong></p><p>COUNTIF используется, когда нужно посчитать количество ячеек, соответствующих определённому условию.</p><p>Общий вид:</p><p><code>=COUNTIF(диапазон, условие)</code></p><p>&nbsp;</p><p>Например, если мы хотим узнать, сколько заказов оплачено через Kaspi:</p><p><code>=COUNTIF(G2:G101,\\\"Оплачено Kaspi\\\")</code></p><p>Здесь:</p><p>G2:G101 — диапазон, в котором выполняется поиск;</p><p>\\\"Оплачено Kaspi\\\" — условие;</p><p>функция считает, сколько раз это значение встречается в диапазоне.</p><p>В учебном датасете таких заказов 61.</p><p>&nbsp;</p><p>Для наличных:</p><p><code>=COUNTIF(G2:G101,\\\"Наличными курьеру\\\")</code></p><p>В датасете таких записей 25.</p><p>&nbsp;</p><p>Обратите внимание: COUNTIF считает количество подходящих ячеек, а не сумму денег.</p><p>Если в столбце находятся суммы заказов и вы напишете COUNTIF, функция будет отвечать на вопрос «сколько ячеек соответствует условию», а не «сколько денег в них находится».</p><p>&nbsp;</p><p><strong>MIN и MAX — минимальное и максимальное значение</strong></p><p>MIN позволяет найти наименьшее значение.</p><p>Например:</p><p><code>=MIN(E2:E101)</code></p><p>Эта формула ищет самый маленький размер заказа в столбце Сумма_Заказа_Тг.</p><p>В учебном датасете минимальная сумма заказа — 700 тг.</p><p>MAX работает наоборот:</p><p><code>=MAX(E2:E101)</code></p><p>Она находит самое большое значение.</p><p>В учебном датасете максимальная сумма заказа — 13 600 тг.</p><p>Таким образом:</p><p>MIN — минимум;</p><p>MAX — максимум.</p><p>Эти функции особенно полезны для быстрого поиска крайних значений без просмотра всех строк вручную.</p><p>При этом MIN и MAX показывают само значение, но не сообщают автоматически, в какой именно строке оно находится.</p><p>&nbsp;</p><p><strong>SUMIF — сумма по условию</strong></p><p>SUMIF нужна, когда требуется не просто сложить весь столбец, а сложить только те значения, которые соответствуют определённому условию.</p><p>Общий вид:</p><p><code>=SUMIF(диапазон_условия, условие, диапазон_суммы)</code></p><p>&nbsp;</p><p>Рассмотрим задачу из нашего датасета.</p><p>Нужно узнать, сколько составила сумма заказов, оплаченных через Kaspi.</p><p>Условие находится в столбце G Статус_Оплаты, а деньги находятся в столбце E Сумма_Заказа_Тг.</p><p>Формула:</p><p><code>=SUMIF(G2:G101,\\\"Оплачено Kaspi\\\",E2:E101)</code></p><p>Если используются точки с запятой:</p><p><code>=SUMIF(G2:G101;\\\"Оплачено Kaspi\\\";E2:E101)</code></p><p>Здесь первый диапазон отвечает на вопрос: «Где искать условие?»</p><p>Условие отвечает на вопрос: «Что именно искать?»</p><p>Последний диапазон отвечает на вопрос: «Какие значения складывать?»</p><p>Результат для учебного датасета — 245 900 тг.</p><p>Для наличных:</p><p><code>=SUMIF(G2:G101,\\\"Наличными курьеру\\\",E2:E101)</code></p><p>Результат — 92 050 тг.</p><p>Это уже настоящий бизнес-анализ: вместо просмотра 100 строк мы получаем сумму продаж по конкретному способу оплаты одной формулой.</p><p>&nbsp;</p><p><strong>Разница между COUNTIF и SUMIF</strong></p><p>Эти функции похожи тем, что обе работают с условием, но выполняют разные действия.</p><p>COUNTIF считает количество подходящих записей.</p><p>SUMIF складывает значения, связанные с подходящими записями.</p><p>Например:</p><p><code>=COUNTIF(G2:G101,\\\"Оплачено Kaspi\\\")</code></p><p>отвечает на вопрос:</p><p>«Сколько заказов оплачено через Kaspi?»</p><p>А:</p><p><code>=SUMIF(G2:G101,\\\"Оплачено Kaspi\\\",E2:E101)</code></p><p>отвечает на вопрос:</p><p>«На какую сумму оформлены заказы с оплатой через Kaspi?»</p><p>Для бизнес-анализа это принципиально разные показатели.</p><p>&nbsp;</p><p><strong>Как читать функцию по частям</strong></p><p>Когда формула становится длиннее, не нужно пытаться запомнить её целиком. Разбирайте её слева направо.</p><p>Например:</p><p><code>=SUMIF(G2:G101,\\\"Оплачено Kaspi\\\",E2:E101)</code></p><p>Шаг 1. SUMIF — понимаем, что хотим получить сумму по условию.</p><p>Шаг 2. G2:G101 — определяем, где находится условие.</p><p>Шаг 3. \\\"Оплачено Kaspi\\\" — определяем само условие.</p><p>Шаг 4. E2:E101 — определяем, какие значения нужно сложить.</p><p>Такой способ разбора помогает не только создавать формулы, но и находить ошибки.</p><p>&nbsp;</p><p><strong>Типичные ошибки</strong></p><p>Одна из распространённых ошибок — выбрать не тот столбец.</p><p>Например, если условие «Оплачено Kaspi» искать в столбце E с суммами, функция не сможет правильно выполнить задачу. Значение Оплачено Kaspi находится в столбце G.</p><p>Другая ошибка — перепутать COUNTIF и SUMIF.</p><p>Если требуется количество заказов, используйте COUNTIF.</p><p>Если требуется сумма денег по условию, используйте SUMIF.</p><p>Ещё одна ошибка — забыть знак = в начале формулы. Без него Google Таблицы не воспринимают запись как формулу.</p><p>Также важно точно писать текстовое условие. Например, Оплачено Kaspi и Оплачено — это разные значения.</p><p>Поэтому при использовании текстовых условий лучше копировать значение непосредственно из таблицы, чтобы не допустить опечатку.</p><p>&nbsp;</p><p><strong>Что мы умеем после этого урока</strong></p><p>Теперь с помощью нескольких функций можно быстро получить базовые показатели продаж:</p><p><code>=SUM(E2:E101) </code>— общая сумма заказов;</p><p><code>=AVERAGE(E2:E101)</code> — средняя сумма заказа;</p><p><code>=COUNTIF(G2:G101,\\\"Оплачено Kaspi\\\")</code> — количество заказов с оплатой Kaspi;</p><p><code>=MIN(E2:E101)</code> — минимальная сумма заказа;</p><p><code>=MAX(E2:E101)</code> — максимальная сумма заказа;</p><p><code>=SUMIF(G2:G101,\\\"Оплачено Kaspi\\\",E2:E101)</code> — сумма заказов с оплатой Kaspi.</p><p>В следующем уроке эти расчёты будут использоваться вместе с другими возможностями Google Таблиц для связывания данных между листами и создания сводных отчётов.</p>\"}'),
(4, 1, '1.3. Связывание листов через XLOOKUP и сводные таблицы', 'xlookup-and-pivot-table', 3, '{\"lab\": \"<p>Связывание таблицы заказов с меню и составление отчёта по категориям и каналам поступления заказов.</p><p>В этой работе нужно самостоятельно объединить сведения из двух листов и подготовить итоговый управленческий отчёт.</p><p>При создании сводных таблиц - создавайте новые сводные таблицы, а не меняйте уже имеющиеся.</p><p>&nbsp;</p><p>Задача 1. Добавьте название и цену товара к заказам</p><p>В листе «Заказы», между столбцами C&nbsp;и D&nbsp;вставьте 2 новых столбца для наименования и цены товара.</p><p>Полностью самостоятельно, не подглядывая в лекцию, заполните столбцы названиями и ценами соответствующих товаров.</p><p>Проверьте несколько результатов вручную по листу «Меню и Товары».</p><p>&nbsp;</p><p>Задача 2. Анализ продаж по категориям товаров</p><p>Используя листы «Заказы» и «Меню и Товары», подготовьте отчёт о продажах по категориям товаров.</p><p>Сначала с помощью XLOOKUP добавьте в таблицу «Заказы», новым столбцом, категорию каждого товара.</p><p>Затем создайте сводную таблицу и определите, какая категория товаров принесла наибольшую сумму продаж.</p><p>Самостоятельно определите, какие поля необходимо использовать в сводной таблице и какую операцию выбрать для расчёта итоговой суммы.</p><p>Не забудьте исключить отменённые заказы.</p><p>&nbsp;</p><p>Задача 3. Сравнение каналов поступления заказов</p><p>Создайте сводную таблицу, которая позволит сравнить количество заказов, поступивших через разные каналы.</p><p>Определите, какой канал обеспечил наибольшее количество заказов.</p><p>&nbsp;</p><p>Задача 4. Сравнение среднего чека по каналам</p><p>Создайте сводную таблицу для сравнения средней суммы заказа в зависимости от канала поступления.</p><p>Определите, через какой канал поступает заказ с наибольшей средней суммой.</p><p>Для выполнения задачи самостоятельно определите, нужны ли дополнительные фильтры и какие именно.</p><p>Дополнительно:</p><p>Сделайте так чтобы суммы отображались без дробной части (целое число - сумма в тенге)</p><p>&nbsp;</p><p>Задача 5. Сделайте управленческий вывод</p><p>На основании сводной таблицы из теоретической части урока определите:</p><p>какой курьер выполнил больше всего заказов;</p><p>какой курьер обеспечил наибольшую сумму продаж.</p><p>Если лидеры по количеству заказов и сумме продаж разные, укажите это отдельно.</p><p>На основании сводных таблиц из лабораторной работы сделайте вывод:</p><p>Какая категория в меню даёт наибольшую сумму продаж;</p><p>Какая наименьшую;</p><p>Какой канал поступления заказов даёт наибольшую сумму продаж;</p><p>Какой наименьшую.</p><p>&nbsp;</p><p>&nbsp;</p><p>После выполнения всех заданий лабораторной работы - удалите все изменения в датасете. Удалите добавленные столбцы и сводные таблицы. Т.е. верните датасет в исходное состояние.</p><p>Можно поступить проще - заново получить и скопировать себе исходный датасет.</p>\", \"tests\": [{\"answers\": [\"Искать способы увеличения прибыли\", \"Группировать заказы и быстро получать итоги ✓\", \"Создавать новые заказы с автоматической скидкой\", \"Формировать для каждого заказа сводные данные\"], \"correct\": null, \"question\": \"Какую бизнес-задачу удобнее всего решать с помощью сводной таблицы?\"}, {\"answers\": [\"В область «Строки» ✓\", \"В область «Столбцы»\", \"В область «Фильтры»\", \"В область «Значения»\"], \"correct\": null, \"question\": \"Куда следует добавить поле Курьер, если нужно получить отдельную строку отчёта для каждого курьера?\"}, {\"answers\": [\"COUNT\", \"SUMMA\", \"SUM ✓\", \"TOTAL\"], \"correct\": null, \"question\": \"Какую операцию следует выбрать для Сумма_Заказа_Тг, если требуется узнать общую сумму заказов каждого курьера?\"}, {\"answers\": [\"Стоимость товара до скидки\", \"Стоимость товара без скидки\", \"Стоимость заказа после применения скидки ✓\", \"Размер скидки в тенге\"], \"correct\": null, \"question\": \"В формуле стоимости со скидкой используется выражение Цена × Количество × (1 − Скидка). Что показывает его результат?\"}, {\"answers\": [\"Потому что XLOOKUP ищет нужный ключ именно в указанном диапазоне ✓\", \"Потому что диапазон автоматически сортирует заказы по дате\", \"Потому что XLOOKUP всегда использует только первый столбец листа\", \"Потому что диапазон определяет формат валюты\"], \"correct\": null, \"question\": \"Почему при XLOOKUP важно правильно выбрать диапазон поиска?\"}], \"theory\": \"<p>В предыдущем уроке мы использовали функции для анализа уже имеющихся данных. Теперь сделаем следующий шаг: научимся брать информацию из одного листа и автоматически подставлять её в другой.</p><p>В учебном датасете службы доставки для этого особенно удобно использовать два листа:</p><p>«Заказы» — здесь хранится информация о заказах;</p><p>«Меню и Товары» — здесь находится справочник товаров: ID товара, название, категория, себестоимость и цена продажи.</p><p>В таблице «Заказы» есть ID_Товара, но нет отдельного названия блюда. Это хороший пример ситуации, когда данные хранятся в разных таблицах, а пользователю нужно видеть их вместе. В листе «Заказы» также есть количество товара, сумма заказа, статус заказа и курьер. Структура этих полей подтверждается учебным датасетом.</p><p>&nbsp;</p><p><strong>Зачем связывать листы</strong></p><p>Откройте в датасете лист Заказы и посмотрите на первые три колонки:</p><p>ORD-001 | CUST-016 | PROD-009 | 2 | ...</p><p>По значению PROD-009 оператору не сразу понятно, какое именно блюдо заказано.</p><p>На листе «Меню и Товары» этот же код связан с конкретным товаром.&nbsp;</p><p>В справочнике есть, например, PROD-001 — Пицца Пепперони (30 см) и PROD-002 — Пицца Маргарита (30 см), а также категории, себестоимость и цены продажи.</p><p>Получается простая логика:</p><p>ID_Товара из Заказов → поиск такого же ID в Меню и Товары → получение нужного значения</p><p>Так таблицы могут работать как связанные части одной небольшой базы данных.</p><p>&nbsp;</p><p><strong>Функция XLOOKUP</strong></p><p>Для такого поиска используем XLOOKUP.</p><p>XLOOKUP позволяет отдельно указать колонку, где выполняется поиск, и колонку, откуда нужно вернуть результат.</p><p>Общий вид:</p><p>=XLOOKUP(что_ищем; где_ищем; что_вернуть)</p><p>Три основные части:</p><p>1. Что ищем</p><p>Значение, которое должно найтись в справочнике.</p><p>В нашем случае это ID_Товара из текущей строки листа «Заказы».</p><p>2. Где ищем</p><p>Колонка справочника, в которой находятся ID товаров.</p><p>В листе «Меню и Товары» это колонка ID_Товара.</p><p>3. Что вернуть</p><p>Колонка, значение из которой нужно получить.</p><p>Если хотим получить название блюда, выбираем колонку Наименование.</p><p>Таким образом, функция отвечает на вопрос:</p><p>«Найди этот ID товара в справочнике и верни название соответствующего товара».</p><p>&nbsp;</p><p>Пример: получение названия блюда</p><p>Допустим, в листе «Заказы» в ячейке C2 находится ID товара.</p><p>Выберите столбец справа от заполненных столбцов датасета (скорее всего у вас это стобец К), и в ячейке соответствующей строки заказа (скорее всего К2) введите формулу:</p><p>=XLOOKUP(C2,\'Меню и Товары\'!A:A,\'Меню и Товары\'!B:B)</p><p>Здесь:</p><p>C2 — ID товара, который ищем;</p><p>\'Меню и Товары\'! A:A — колонка ID товаров;</p><p>\'Меню и Товары\'! B:B — колонка названий товаров.</p><p>Название листа заключено в одинарные кавычки, потому что в нём есть пробелы.</p><p>После ввода формулы Google Таблицы находят соответствующий ID и возвращают название товара.</p><p>Например, если найден PROD-009, результатом будет название этого товара — «Темпура ролл с креветкой».</p><p>Естественно, можно сделать автозаполнение по столбцу, как и в Excel.</p><p>Внимание:</p><p>Здесь, и в дальнейших примерах, конкретные имена столбцов, адреса ячеек, ID заказов, клиентов, товаров, наименования - могут отличаться в вашем реальном датасете. Поэтому ориентируйтесь самостоятельно по месту.</p><p>Главное понять принцип.</p><p>&nbsp;</p><p><strong>Получение цены из того же справочника</strong></p><p>Точно таким же способом можно получить цену продажи.</p><p>Меняется только третий аргумент XLOOKUP — колонка, из которой возвращается результат.</p><p>В листе «Меню и Товары» цена продажи находится в колонке Цена_Продажи_Тг. Например, для PROD-001 указана цена 3200 тг, а для PROD-002 — 2600 тг.</p><p>Можно указать цену продажи данного товара в соседнем столбце (относительно предыдущего примера) (L).</p><p>В ячейку L2 введите следующую формулу:</p><p>=XLOOKUP(C2,\'Меню и Товары\'!A:A,\'Меню и Товары\'!E:E)</p><p>В столбце L отобразится цена товара с данным ID.</p><p>(например: для PROD-009 - Темпура ролл с креветкой - 3100)</p><p>&nbsp;</p><p>Если в заказе указано количество 2, то после получения цены можно рассчитать стоимость без скидки:</p><p>Количество × Цена.</p><p>В ячейке&nbsp;M2 введите формулу:</p><p>=L2*D2</p><p>Например:</p><p>2 × 3100 = 6200 тг</p><p>Так мы не вводим цену блюда вручную в каждый заказ.&nbsp;</p><p>Если цена берётся из единого справочника, вероятность случайно указать неправильную цену становится меньше.</p><p>(В исходном датасете уже есть столбец с итоговой стоимостью, т.е. то же, что мы рассчитали сейчас формулой. Это сделано сознательно, чтобы можно было использовать эти данные на предыдущем уроке и, при этом, не усложнять. В реальности такие данные, конечно, рассчитываются формулой).</p><p>&nbsp;</p><p><strong>Почему важно правильно выбирать колонки</strong></p><p>При работе с XLOOKUP новичок часто ошибается не в самой функции, а в диапазонах.</p><p>Нужно различать:</p><p>где ищем</p><p>и</p><p>что возвращаем.</p><p>Если искать ID в колонке названий, совпадения не найдутся.</p><p>Если искать ID правильно, но вернуть колонку себестоимости вместо цены продажи, таблица покажет число, которое выглядит правдоподобно, но отвечает уже на другой вопрос.</p><p>В нашем справочнике отдельно хранятся:</p><p>ID товара;</p><p>наименование;</p><p>категория;</p><p>себестоимость;</p><p>цена продажи.</p><p>Поэтому перед созданием формулы полезно сначала определить бизнес-вопрос:</p><p>«Что я хочу узнать по ID товара?»</p><p>Затем выбрать соответствующую колонку результата.</p><p>&nbsp;</p><p><strong>Расчет стоимости со скидкой</strong></p><p>После получения цены можно выполнять обычные арифметические расчёты, которые мы уже использовали в предыдущем уроке.</p><p>Допустим:</p><p>цена товара — 3100 тг;</p><p>количество — 2;</p><p>скидка — 10%.</p><p>Сначала рассчитываем стоимость без скидки:</p><p>3100 × 2 = 6200</p><p>Размер скидки:</p><p>6200 × 10% = 620</p><p>Стоимость после скидки:</p><p>6200 − 620 = 5580</p><p>В таблице это можно объединить в одну формулу:</p><p>=Цена*Количество*(1-Скидка)</p><p>Если скидка записана как 10%, формула автоматически учитывает её как десять процентов.</p><p>Например:</p><p>=L2*D2*(1-10%)</p><p>Здесь конкретные буквы столбцов зависят от того, как вы разместили новые расчётные поля. Важно не запомнить буквы, а понимать последовательность расчёта:</p><p>цена × количество × (1 − скидка).</p><p>Скидка в исходной структуре листа «Заказы» отдельным полем не указана. Поэтому при учебном расчёте её можно вынести в отдельный дополнительный столбец только для выполнения расчёта, предусмотренного программой урока.</p><p>&nbsp;</p><p><strong>Что делать с отменёнными заказами</strong></p><p>В датасете есть разные статусы заказа. Для выполненных заказов указано «Доставлено», а для отменённых — «Отменено»; у отменённых заказов вместо курьера используется символ —.</p><p>Это важно при построении отчёта.</p><p>Если задача отчёта — показать продажи курьеров, отменённые заказы не следует автоматически считать продажами курьера. Сначала нужно определить, какие строки относятся к фактически доставленным заказам.</p><p>В самой лабораторной работе студенту потребуется самостоятельно выбрать подход к подготовке данных перед сводным отчётом, используя уже изученные возможности таблиц.</p><p>&nbsp;</p><p>В конце работы с XLOOKUP очистите все созданные вами ячейки с формулами и функциями.</p><p>&nbsp;</p><p><strong>Сводная таблица</strong></p><p>Сводная таблица, или Pivot Table, нужна для быстрого подведения итогов по большому количеству строк.</p><p>В нашем датасете лист «Заказы» содержит отдельные записи заказов. Для каждого заказа указаны, в частности, его ID, количество, сумма заказа, статус заказа и курьер.&nbsp;</p><p>Например, если нужно узнать, какую общую сумму заказов обслужил каждый курьер, не нужно вручную искать и складывать строки. Сводная таблица сама сгруппирует записи по курьеру и рассчитает итог.</p><p>Логика простая:</p><p>много строк заказов → группировка по курьеру → итоговая сумма по каждому курьеру</p><p>Для нашего отчёта используются реальные данные листа «Заказы»:</p><p>Группировка: столбец I — Курьер</p><p>Показатель: столбец E — Сумма_Заказа_Тг</p><p>Например, исходные строки могут содержать:</p><p>ORD-001 → 6200 тг → Дмитрий (Курьер #2)</p><p>ORD-002 → 3400 тг → Дмитрий (Курьер #2)</p><p>ORD-003 → 3900 тг → Алихан (Курьер #1)</p><p>Сводная таблица соберёт все строки каждого курьера и покажет их общий результат. Эти значения не нужно рассчитывать вручную — их рассчитает Google Таблицы на основании исходных данных.</p><p>Важно учитывать поле Статус_Заказа. В датасете встречаются, например, статусы Доставлено и Отменено. Поэтому перед построением отчёта о фактических продажах нужно исключить из расчёта отменённые заказы.</p><p>&nbsp;</p><p><strong>Создание сводной таблицы</strong></p><p>Для первого отчёта будем использовать непосредственно лист «Заказы».</p><p>&nbsp;</p><p>Шаг 1. Выделите исходные данные</p><p>На листе «Заказы» выделите всю таблицу с заголовками:</p><p>В меню Google Таблиц выберите:</p><p>Insert (Вставка) → Pivot table (Сводная таблица).</p><p>После этого Google Таблицы предложат выбрать Data&nbsp;range (диапазон) и место размещения сводной таблицы.</p><p>Диапазон (\'Заказы\'!1:1000) - оставьте без изменений.</p><p>Для учебной работы можно разместить сводную таблицу на New&nbsp;sheet&nbsp;(новом листе). Так исходные данные листа «Заказы» останутся без изменений.</p><p>Нажмите кнопку Create.</p><p>Откроется редактор (мастер) сводной таблицы (pivot table).</p><p>&nbsp;</p><p>Шаг 2. Добавьте группировку по курьеру</p><p>В редакторе сводной таблицы найдите область Rows (Строки).</p><p>Нажмите Add (Добавить) и выберите:</p><p>Курьер</p><p>&nbsp;</p><p>Теперь Google Таблицы будут создавать отдельную строку отчёта для каждого значения поля Курьер.</p><p>&nbsp;</p><p>Шаг 3. Добавьте сумму продаж</p><p>В редакторе найдите область Values (Значения).</p><p>Нажмите Add (Добавить) и выберите:</p><p>Сумма_Заказа_Тг</p><p>&nbsp;</p><p>После добавления Google Таблицы могут автоматически выбрать способ расчёта.&nbsp;</p><p>В настройке этого показателя выберите:</p><p>Summarize&nbsp;by (Сводить по) → SUM</p><p>То есть:</p><p>Строки → Курьер</p><p>Значения → Сумма_Заказа_Тг</p><p>Сводить по → SUM</p><p>В результате получится отчёт, в котором каждая строка соответствует курьеру, а рядом отображается общая сумма заказов этого курьера.</p><p>Обратите внимание, также, на общую сумму.</p><p>Сейчас в неё входят и суммы отменённых заказов то же.</p><p>&nbsp;</p><p>Шаг 4. Отфильтруйте отменённые заказы</p><p>Для отчёта именно о выполненных продажах добавьте в область Filtres (Фильтры) поле:</p><p>Статус_Заказа</p><p>(столбец H листа «Заказы»).</p><p>В настройках фильтра оставьте:</p><p>Доставлено</p><p>и исключите:</p><p>Отменено</p><p>Теперь сумма в сводной таблице будет рассчитываться только по доставленным заказам.</p><p>&nbsp;</p><p>Получается полный набор настроек:</p><p>Фильтры → Статус_Заказа → Доставлено</p><p>Строки → Курьер</p><p>Значения → Сумма_Заказа_Тг → SUM</p><p>Это уже полноценный сводный отчёт по фактическим продажам курьеров.</p><p>&nbsp;</p><p><strong>Как думать при работе со сводной таблицей</strong></p><p>Главное — сначала сформулировать бизнес-вопрос, а затем определить, какие реальные поля датасета нужны для ответа.</p><p>&nbsp;</p><p>Вопрос: «Какую сумму доставленных заказов обслужил каждый курьер?»</p><p>Используем:</p><p>Фильтры: Статус_Заказа → оставить Доставлено;</p><p>Строки: Курьер;</p><p>Значения: Сумма_Заказа_Тг;</p><p>Операция: SUM .</p><p>То есть сводная таблица группирует данные из столбца I Курьер, а значения берёт из столбца E Сумма_Заказа_Тг.</p><p>&nbsp;</p><p>Вопрос: «Сколько доставленных заказов обработал каждый курьер?»</p><p>Теперь нас интересует не сумма денег, а количество заказов.</p><p>Используем:</p><p>Фильтры: Статус_Заказа → Доставлено;</p><p>Строки: Курьер;</p><p>Значения: ID_Заказа;</p><p>Операция: COUNTA или другой доступный вариант подсчёта непустых значений.</p><p>Здесь используется столбец A ID_Заказа, потому что каждый заказ имеет собственный идентификатор.</p><p>Получается:</p><p>Фильтры → Статус_Заказа → Доставлено</p><p>Строки → Курьер</p><p>Значения → ID_Заказа → COUNTA</p><p>Теперь в отчёте можно увидеть, сколько доставленных заказов приходится на каждого курьера.</p><p>&nbsp;</p><p>Вопрос: «Сколько товаров было доставлено каждым курьером?»</p><p>Это уже другой показатель.</p><p>Используем:</p><p>Фильтры: Статус_Заказа → Доставлено;</p><p>Строки: Курьер;</p><p>Значения: Количество;</p><p>Операция: SUM.</p><p>Здесь используется столбец D Количество. Он показывает количество единиц товара в конкретном заказе.</p><p>Получается:</p><p>Фильтры → Статус_Заказа → Доставлено</p><p>Строки → Курьер</p><p>Значения → Количество → SUM</p><p>Это показывает уже не количество заказов и не сумму продаж, а общее количество единиц товара в доставленных заказах каждого курьера.</p><p>&nbsp;</p><p>Таким образом, одна и та же исходная таблица «Заказы» позволяет строить разные отчёты. Меняется не исходный датасет, а вопрос и соответствующая настройка сводной таблицы.</p><p>Сводная таблица не создаёт новую базу данных. Она строит итоговый отчёт на основании выбранного диапазона исходных данных.</p><p>В нашем случае основные поля для первого отчёта такие:</p><p>I — Курьер → по этому полю группируем записи.</p><p>E — Сумма_Заказа_Тг → этот показатель суммируем.</p><p>H — Статус_Заказа → используем для отбора только доставленных заказов.</p><p>A — ID_Заказа → используем, если нужно посчитать количество заказов.</p><p>D — Количество → используем, если нужно посчитать количество проданных единиц товара.</p><p>&nbsp;</p><p><strong>Что нужно запомнить</strong></p><p>XLOOKUP используется, когда нужно найти значение по ключу в одном диапазоне и вернуть связанное значение из другого диапазона.</p><p>В нашем датасете таким ключом является ID_Товара.</p><p>Связь выглядит так:</p><p>Заказы.ID_Товара → Меню и Товары.ID_Товара → нужное поле из Меню и Товары</p><p>С помощью XLOOKUP можно получить название, цену и другие сведения из таблицы Меню и Товары, являющуюся, фактически, справочником товаров.</p><p>&nbsp;</p><p>Сводная таблица используется уже для другого действия: она группирует множество строк и быстро показывает итоговые показатели.</p><p>Для отчёта по курьерам:</p><p>Строки → Курьер</p><p>Значения → показатель, который нужно суммировать или считать</p><p>&nbsp;</p><p>Эти два инструмента решают разные задачи: XLOOKUP помогает соединить сведения из разных листов, а Pivot Table помогает превратить большое количество строк в понятный итоговый отчёт.</p>\"}');
INSERT INTO `lessons` (`id`, `section_id`, `title_ru`, `slug`, `lesson_order`, `content`) VALUES
(5, 1, '1.4. Визуализация данных и наглядная отчетность', 'charts', 4, '{\"theory\":\"<p>До этого урока мы использовали Google Таблицы в основном для расчётов и создания сводных таблиц. Теперь научимся представлять результаты этих расчётов в графическом виде.<\\/p><p>&nbsp;<\\/p><p>Числа в таблице удобны для точного анализа, но руководителю не всегда нужно (есть время) просматривать десятки строк. Хорошо построенная диаграмма позволяет быстрее увидеть разницу между категориями, понять, какой день был наиболее результативным, и заметить изменение выручки во времени.<\\/p><p>&nbsp;<\\/p><p>В этом уроке будем работать с тремя видами диаграмм:<\\/p><p>круговой диаграммой — для показа долей;<\\/p><p>столбчатой диаграммой — для сравнения показателей между категориями;<\\/p><p>линейной диаграммой — для отображения изменения показателя во времени.<\\/p><p>&nbsp;<\\/p><p>Все практические примеры выполняются на учебном датасете службы доставки.<\\/p><p>&nbsp;<\\/p><p>Для визуализации продаж нам понадобятся прежде всего два листа: «Меню и Товары» и &nbsp;«Заказы».<\\/p><p>&nbsp;<\\/p><p>В предыдущем уроке мы уже использовали XLOOKUP для связывания листов и сводные таблицы для группировки заказов. Поэтому в этом уроке будем использовать эти уже знакомые возможности как основу подготовки данных для диаграмм.<\\/p><p>Для управленческого отчёта важно отдельно учитывать поле «Статус_Заказа».&nbsp;<\\/p><p>В датасете встречаются доставленные и отменённые заказы. Если мы хотим показать фактическую выручку, в отчёт следует включать только доставленные заказы.<\\/p><p>&nbsp;<\\/p><p>Почему диаграмма строится не непосредственно по исходной таблице ?<\\/p><p>Новичку часто хочется сразу выделить весь лист «Заказы» и нажать кнопку создания диаграммы. Это не всегда приводит к полезному результату.<\\/p><p>В исходной таблице каждая строка представляет отдельный заказ.&nbsp;<\\/p><p>Руководителю же чаще нужен итог:<\\/p><p>выручка по категориям;<\\/p><p>выручка по дням недели;<\\/p><p>выручка по датам;<\\/p><p>продажи по товарам.<\\/p><p>&nbsp;<\\/p><p>Поэтому сначала нужно подготовить небольшую итоговую таблицу.<\\/p><p>Например, вместо 100 строк заказов можно получить таблицу из нескольких строк:<\\/p><figure class=\\\"table\\\"><table><tbody><tr><td>Категория&nbsp;<\\/td><td>Выручка<\\/td><\\/tr><tr><td>Пицца&nbsp;<\\/td><td>91 900<\\/td><\\/tr><tr><td>Суши и Роллы<\\/td><td>72 700<\\/td><\\/tr><tr><td>Напитки&nbsp;<\\/td><td>20 250<\\/td><\\/tr><\\/tbody><\\/table><\\/figure><p>А уже эту небольшую таблицу превратить в диаграмму.<\\/p><p>&nbsp;<\\/p><p>Это важный принцип визуализации:<\\/p><p>сначала сформулировать бизнес-вопрос, затем подготовить итоговые данные и только после этого выбирать подходящий тип диаграммы.<\\/p><p>&nbsp;<\\/p><p><strong>Круговая диаграмма<\\/strong><\\/p><p>Круговая диаграмма показывает, какую долю от общей суммы занимает каждая категория.<\\/p><p>Она особенно удобна, когда категорий немного и нужно показать их соотношение.<\\/p><p>Например, в нашем датасете рассмотрим три категории:<\\/p><p>Пицца;<\\/p><p>Суши и Роллы;<\\/p><p>Напитки.<\\/p><p>Для фактически доставленных заказов сумма продаж этих категорий составляет:<\\/p><p>Пицца — 91 900 тг;<\\/p><p>Суши и Роллы — 72 700 тг;<\\/p><p>Напитки — 20 250 тг.<\\/p><p>Общая сумма этих трёх категорий — 184 850 тг.<\\/p><p>Если представить эти значения в виде круговой диаграммы, становится хорошо видно, что наибольшую долю занимает пицца.<\\/p><p>Доля пиццы составляет примерно 49,7%, суши и роллов — 39,3%, напитков — 11,0%.<\\/p><p>При этом важно понимать: круговая диаграмма показывает доли только выбранного набора данных.&nbsp;<\\/p><p>В данном примере мы сравниваем именно три категории, а не весь ассортимент службы доставки.<\\/p><p>&nbsp;<\\/p><p>Подготовка данных для круговой диаграммы<\\/p><p>Для построения круговой диаграммы нам нужно получить сумму доставленных заказов по категориям товаров.<\\/p><p>В исходном листе «Заказы» нет отдельного столбца «Категория». На этом листе есть ID_Товара, а название и категория товара находятся в листе «Меню и Товары».<\\/p><p>Поэтому в данном случае не нужно пытаться использовать SUMIF непосредственно на листе «Заказы». Вместо этого воспользуемся сводной таблицей, которую изучили в предыдущем уроке.<\\/p><p>Сводная таблица позволит одновременно:<\\/p><p>- связать данные о товаре с его категорией;<\\/p><p>- сгруппировать заказы по категориям;<\\/p><p>- исключить отменённые заказы;<\\/p><p>- посчитать общую сумму доставленных заказов по каждой категории.<\\/p><p>&nbsp;<\\/p><p>Подготовка данных для сводной таблицы<\\/p><p>Сначала нам нужно добавить категорию товара к каждой записи заказа.<\\/p><p>Перейдите на лист «Заказы».<\\/p><p>Справа от существующих данных используйте дополнительный столбец (например L).<\\/p><p>Назовите его:<\\/p><p>Категория<\\/p><p>В первой строке данных нового столбца используйте XLOOKUP.<\\/p><p>На листе «Заказы» ID_Товара находится в столбце C.<\\/p><p>На листе «Меню и Товары»:<\\/p><p>столбец A — ID_Товара;<\\/p><p>столбец C — Категория.<\\/p><p>Поэтому для первой строки заказа используйте:<\\/p><p><code>=XLOOKUP(C2,\'Меню и Товары\'!A:A,\'Меню и Товары\'!C:C)<\\/code><\\/p><p>Формула означает:<\\/p><p>C2 — ID товара текущего заказа;<\\/p><p>\'Меню и Товары\'!A:A — диапазон, в котором ищем ID товара;<\\/p><p>\'Меню и Товары\'!C:C — диапазон, из которого возвращаем категорию.<\\/p><p>После ввода формулы заполните её вниз для остальных заказов.<\\/p><p>Теперь у каждой строки листа «Заказы» есть категория соответствующего товара.<\\/p><p>&nbsp;<\\/p><p>Создание сводной таблицы по категориям.<\\/p><p>Перед созданием - выделите всю таблицу «Заказы».<\\/p><p>Теперь создайте новую сводную таблицу на основании листа «Заказы».<\\/p><p>Разместите новую сводную таблицу на новом листе.<\\/p><p>В редакторе сводной таблицы настройте поля следующим образом.<\\/p><p>В область «Фильтры» добавьте: Статус_Заказа;<\\/p><p>В настройках фильтра оставьте только: Доставлено;<\\/p><p>В область «Строки» добавьте: Категория;<\\/p><p>В область «Значения» добавьте: Сумма_Заказа_Тг;<\\/p><p>Для показателя «Сумма_Заказа_Тг» выберите операцию: SUM;<\\/p><p>&nbsp;<\\/p><p>Теперь Google Таблицы сгруппируют доставленные заказы по категориям и самостоятельно рассчитают общую сумму продаж каждой категории.<\\/p><p>&nbsp;<\\/p><p>Построение круговой диаграммы<\\/p><p>Теперь сводная таблица уже содержит именно те данные, которые нужны для визуализации.<\\/p><p>Выделите в сводной таблице названия категорий и итоговые суммы продаж.<\\/p><p>Создайте диаграмму (Insert&nbsp;→ Chart).<\\/p><p>В панели настройки диаграммы (Chart&nbsp;editor) выберите тип:<\\/p><p>Круговая диаграмма (Pie&nbsp;chart) (pie - пирог, торт).<\\/p><p>Google Таблицы будут использовать названия категорий как элементы диаграммы, а суммы продаж — для определения размера каждого сектора.<\\/p><p>&nbsp;<\\/p><p>Проверьте, что:<\\/p><p>категории используются как подписи;<\\/p><p>сумма продаж используется как числовой показатель;<\\/p><p>в расчётах учитываются только заказы со статусом «Доставлено».<\\/p><p>&nbsp;<\\/p><p>Настройка подписей и легенды<\\/p><p>Для круговой диаграммы подписи данных включены по умолчанию.<\\/p><p>В качестве подписей удобно использовать процентное соотношение категорий. Тогда руководитель сможет сразу увидеть, какую долю продаж занимает каждая категория.<\\/p><p>Например, если одна категория занимает почти половину всей суммы, это будет заметно не только по размеру сектора, но и по процентной подписи.<\\/p><p>Заголовок диаграммы должен объяснять, что именно показывает график.<\\/p><p>Например:<\\/p><p>«Выручка по категориям товаров»<\\/p><p>Такой заголовок лучше, чем просто «Продажи», потому что сразу сообщает читателю, какой показатель и в каком разрезе представлен.<\\/p><p>&nbsp;<\\/p><p>В результате мы выполнили следующую последовательность:<\\/p><p>Заказы → XLOOKUP → Категория → Сводная таблица → фильтр «Доставлено» → сумма продаж по категориям → круговая диаграмма.<\\/p><p>&nbsp;<\\/p><p>Это хороший пример рабочего процесса бизнес-аналитики: сначала подготовить данные, затем получить итоговый показатель и только после этого представить его графически.<\\/p><p>Не следует строить диаграмму непосредственно по 100 строкам исходных заказов, если бизнес-вопрос касается итоговой выручки по категориям. Сначала нужно получить агрегированные данные, которые непосредственно отвечают на этот вопрос.<\\/p><p>&nbsp;<\\/p><p>После построения и анализа диаграммы - удалите диаграмму, сводную таблицу и столбец с категориями.<\\/p><p>&nbsp;<\\/p><p>&nbsp;<\\/p><p><strong>Столбчатая диаграмма<\\/strong><\\/p><p>Столбчатая диаграмма хорошо подходит для сравнения нескольких значений.<\\/p><p>В нашем случае с её помощью можно сравнить объём продаж по дням недели.<\\/p><p>&nbsp;<\\/p><p>Как получить день недели ?<\\/p><p>В листе «Заказы» дата и время заказа находятся в столбце &nbsp;J &nbsp;«Дата_Заказа».<\\/p><p>Для построения отчёта по дням недели нужно получить название дня из даты.<\\/p><p>Для этого можно создать дополнительный учебный столбец «День_Недели». Это временный вспомогательный столбец, необходимый только для данного анализа.<\\/p><p>В ячейке этого столбца для первой строки заказа можно использовать функцию TEXT, например:<\\/p><p>=TEXT(J2,\\\"dddd\\\")<\\/p><p>Функция TEXT здесь используется только для того, чтобы преобразовать дату в название дня недели, для выполнения задачи текущего урока. Запоминать его как отдельный аналитический инструмент не требуется.<\\/p><p>&nbsp;<\\/p><p>Создайте сводную таблицу<\\/p><p>Выделите данные листа «Заказы», включая новый столбец&nbsp; K «День_Недели».<\\/p><p>Вставьте сводную таблицу на новом листе.<\\/p><p>В область «Фильтры» добавьте поле: Статус_Заказа;<\\/p><p>В фильтре оставьте только значение: Доставлено;<\\/p><p>В область «Строки» добавьте: День_Недели;<\\/p><p>В область «Значения» добавьте: Сумма_Заказа_Тг;<\\/p><p>Для поля «Сумма_Заказа_Тг» установите способ расчёта: SUM.<\\/p><p>Для учебного датасета результат должен соответствовать следующим значениям:<\\/p><p>&nbsp;<\\/p><figure class=\\\"table\\\"><table><tbody><tr><td><i>День_Недели<\\/i><\\/td><td>SUM of Сумма_Заказа_Тг<\\/td><\\/tr><tr><td>Friday<\\/td><td>53900<\\/td><\\/tr><tr><td>Monday<\\/td><td>47800<\\/td><\\/tr><tr><td>Saturday<\\/td><td>77150<\\/td><\\/tr><tr><td>Sunday<\\/td><td>39550<\\/td><\\/tr><tr><td>Thursday<\\/td><td>31300<\\/td><\\/tr><tr><td>Tuesday<\\/td><td>40950<\\/td><\\/tr><tr><td>Wednesday<\\/td><td>47300<\\/td><\\/tr><\\/tbody><\\/table><\\/figure><p>&nbsp;<\\/p><p>Если Google Таблицы расположили дни недели не в порядке от понедельника до воскресенья - для данного учебного примера оставьте так. Расположить дни недели в правильном порядке можно, но это излишне усложнит наш учебный пример.&nbsp;<\\/p><p>&nbsp;<\\/p><p>Создайте столбчатую диаграмму.<\\/p><p>Выделите в сводной таблице столбцы:<\\/p><p>День_Недели<\\/p><p>и<\\/p><p>SUM Сумма_Заказа_Тг.<\\/p><p>Выберите:<\\/p><p>Insert&nbsp;→ Chart<\\/p><p>Google Таблицы создадут, по умолчанию, столбчатую диаграмму.<\\/p><p>На горизонтальной оси должны находиться дни недели.<\\/p><p>На вертикальной оси должна находиться сумма продаж в тенге.<\\/p><p>&nbsp;<\\/p><p>Добавьте подписи данных.<\\/p><p>Дважды щёлкните по диаграмме.<\\/p><p>Справа появится&nbsp;Chart&nbsp;Editor (Редактор диаграммы).<\\/p><p>Перейдите на вкладку&nbsp;Customize (Настроить).<\\/p><p>Откройте вкладку&nbsp;Series (Ряды или Серии).<\\/p><p>Промотайте вниз.<\\/p><p>Отметьте&nbsp;checkbox&nbsp;Data&nbsp;Lables&nbsp;(Подписи данных).<\\/p><p>Теперь над каждым столбцом будет показана точная сумма продаж.<\\/p><p>Это удобно, когда нужно не только увидеть, какой столбец выше, но и узнать конкретное значение.<\\/p><p>Однако если столбцов много, подписи могут сделать диаграмму перегруженной. Поэтому всегда проверяйте читаемость готового отчёта.<\\/p><p>&nbsp;<\\/p><p>Настройте заголовок.<\\/p><p>Дважды щёлкните по заголовку диаграммы и введите более правильный заголовок&nbsp;<\\/p><p>\\\"Выручка по дням недели\\\"<\\/p><p>Сделайте двойной щелчок по заголовку вертикальной оси и введите:<\\/p><p>\\\"Выручка, тг\\\".<\\/p><p>Сделайте двойной щелчок по заголовку горизонтальной оси и введите:<\\/p><p>\\\"День недели\\\"<\\/p><p>&nbsp;<\\/p><p>Что показывает готовая диаграмма<\\/p><p>После настройки диаграммы сразу видно, что в учебном датасете максимальная выручка от доставленных заказов приходится на субботу — 77 150 тг.<\\/p><p>Минимальная выручка приходится на четверг — 31 300 тг.<\\/p><p>&nbsp;<\\/p><p>После завершения работы с диаграммой, на листе \\\"Заказы\\\" удалите временный столбец \\\"День Недели\\\".<\\/p><p>&nbsp;<\\/p><p><strong>Линейная диаграмма<\\/strong><\\/p><p>Линейная диаграмма используется, прежде всего, для показа изменения показателя во времени.<\\/p><p>Например, руководителю может быть интересно не только, сколько было продаж всего, но и как менялась выручка в течение периода.<\\/p><p>Для такого отчёта нам понадобятся:<\\/p><p>Дата_Заказа;<\\/p><p>Сумма_Заказа_Тг;<\\/p><p>Статус_Заказа.<\\/p><p>&nbsp;<\\/p><p>Сначала нужно получить итоговую сумму доставленных заказов для каждой даты.<\\/p><p>В нашем датасете даты заказов находятся в периоде с июня по август 2026 года. При этом заказы есть не на каждый календарный день. Это нормально.<\\/p><p>Подготовленная таблица должна иметь примерно такой принцип:<\\/p><figure class=\\\"table\\\"><table><tbody><tr><td>Дата<\\/td><td>Выручка<\\/td><\\/tr><tr><td>03.06.2026&nbsp;<\\/td><td>&nbsp;11 950<\\/td><\\/tr><tr><td>06.06.2026&nbsp;<\\/td><td>&nbsp;2 300<\\/td><\\/tr><tr><td>07.06.2026&nbsp;<\\/td><td>&nbsp;3 200<\\/td><\\/tr><\\/tbody><\\/table><\\/figure><p>и так далее по датам, для которых есть доставленные заказы.<\\/p><p>&nbsp;<\\/p><p>Здесь важно не перепутать отдельный заказ и итог за день. Если в один день было несколько заказов, их суммы должны быть объединены в одно значение за этот день.<\\/p><p>Для такой подготовки удобно использовать сводную таблицу.<\\/p><p>&nbsp;<\\/p><p>Создайте новую сводную таблицу на основании листа «Заказы».<\\/p><p>В область «Фильтры» добавьте: Статус_Заказа → Доставлено.<\\/p><p>В область «Строки» добавьте: Дата_Заказа.<\\/p><p>В область «Значения» добавьте: Сумма_Заказа_Тг → SUM.<\\/p><p>В результате Google Таблицы сгруппируют заказы по датам и посчитают общую сумму доставленных заказов для каждой даты.<\\/p><p>&nbsp;<\\/p><p>После этого выделите получившуюся таблицу и создайте линейную диаграмму.<\\/p><p>Insert&nbsp;→ Chart<\\/p><p>В Chart&nbsp;Editor, на вкладке Setup&nbsp;выберите Chart&nbsp;Type&nbsp;→ Line&nbsp;Chart (линейная диаграмма)<\\/p><p>На горизонтальной оси будет время.<\\/p><p>На вертикальной оси — выручка.<\\/p><p>Линия позволит увидеть периоды роста и снижения продаж.<\\/p><p>&nbsp;<\\/p><p><strong>Важное отличие трёх диаграмм<\\/strong><\\/p><p>Выбор диаграммы зависит от бизнес-вопроса.<\\/p><p>Если вопрос звучит:<\\/p><p>«Какую долю занимает каждая категория?»<\\/p><p>подходит круговая диаграмма.<\\/p><p>Если вопрос:<\\/p><p>«Как отличаются продажи между несколькими группами?»<\\/p><p>подходит столбчатая диаграмма.<\\/p><p>Если вопрос:<\\/p><p>«Как менялась выручка со временем?»<\\/p><p>подходит линейная диаграмма.<\\/p><p>&nbsp;<\\/p><p>Нельзя считать один тип диаграммы универсальным для всех задач.<\\/p><p>Например, линейная диаграмма плохо подходит для демонстрации долей категорий, а круговая диаграмма плохо показывает изменение выручки по датам.<\\/p><p>&nbsp;<\\/p><p><strong>Как проверить готовую диаграмму<\\/strong><\\/p><p>Перед тем как использовать диаграмму в отчёте, проверьте несколько вещей.<\\/p><p>- Правильно ли выбран диапазон данных?<\\/p><p>- Не попали ли в расчёт отменённые заказы?<\\/p><p>- Правильно ли определены категории и значения?<\\/p><p>- Соответствует ли тип диаграммы поставленному вопросу?<\\/p><p>- Понятны ли подписи?<\\/p><p>- Видна ли легенда, если она нужна?<\\/p><p>- Можно ли определить показатель без дополнительного объяснения?<\\/p><p>Если хотя бы на один вопрос ответ отрицательный, диаграмму нужно проверить и при необходимости изменить.<\\/p><p>&nbsp;<\\/p><p><strong>Что нужно запомнить<\\/strong><\\/p><p>Диаграмма — это графическое представление подготовленных данных.<\\/p><p>Перед построением диаграммы нужно определить бизнес-вопрос и подготовить итоговую таблицу.<\\/p><p>Круговая диаграмма показывает доли.<\\/p><p>Столбчатая диаграмма удобна для сравнения категорий или групп.<\\/p><p>Линейная диаграмма показывает изменение показателя во времени.<\\/p><p>Подписи данных помогают увидеть точные значения.<\\/p><p>Легенда помогает определить, какой элемент графика соответствует конкретной категории.<\\/p><p>Главная задача визуализации — не украсить таблицу, а сделать бизнес-информацию понятной с первого взгляда.<\\/p><p>&nbsp;<\\/p><p>После завершения работы с диаграммами - удалите все изменения и сводные таблицы.<\\/p><p>Верните датасет в исходное состояние или сделайте новую копию с исходного варианта.<\\/p>\",\"tests\":[{\"question\":\"Какой принцип следует использовать перед созданием диаграммы?\",\"answers\":[\"Сначала выбрать тип диаграммы, а затем искать подходящие данные\",\"Сначала сформулировать бизнес-вопрос и подготовить данные ✓\",\"Всегда строить график по всей исходной таблице\",\"Сначала изменить оформление таблицы, а потом определить показатель\"],\"correct\":null},{\"question\":\"Какой тип диаграммы наиболее удобен для сравнения нескольких категорий между собой?\",\"answers\":[\"Круговая диаграмма\",\"Линейная диаграмма\",\"Диаграмма без осей\",\"Столбчатая диаграмма ✓\"],\"correct\":null},{\"question\":\"Какой тип диаграммы лучше всего подходит для отображения доли каждой категории в общей сумме?\",\"answers\":[\"Круговая диаграмма ✓\",\"Линейная диаграмма\",\"Столбчатая диаграмма\",\"Точечная диаграмма\"],\"correct\":null},{\"question\":\"Какой тип диаграммы лучше всего показывает изменение показателя во времени?\",\"answers\":[\"Круговая диаграмма\",\"Столбчатая диаграмма\",\"Линейная диаграмма ✓\",\"Кольцевая диаграмма\"],\"correct\":null},{\"question\":\"Какой вариант лучше всего подходит для отображения выручки компании по месяцам в течение года?\",\"answers\":[\"Круговая диаграмма\",\"Линейная диаграмма ✓\",\"Диаграмма без осей\",\"Круговая диаграмма с одной категорией\"],\"correct\":null},{\"question\":\"Какой принцип является правильным при создании наглядного бизнес-отчёта?\",\"answers\":[\"Использовать как можно больше диаграмм и подписей\",\"В первую очередь выбирать диаграмму с наиболее привлекательным внешним видом.\",\"Сначала подготовить данные и определить задачу, а затем выбрать подходящий тип диаграммы ✓\",\"Сначала выбрать подходящий тип диаграммы, а затем добавить в неё подходящие бизнес-данные.\"],\"correct\":null}],\"lab\":\"<p>В этой лабораторной работе нужно самостоятельно подготовить графический отчёт о самых популярных позициях меню службы доставки.<\\/p><p>Задания используют материал текущего урока и ранее изученные возможности Google Таблиц: сводные таблицы, XLOOKUP и работу с данными листов «Заказы» и «Меню и Товары».<\\/p><p>Не изменяйте исходные данные. Для отчёта создавайте отдельные сводные таблицы и вспомогательные области.<\\/p><p>&nbsp;<\\/p><p>Задача 1. Подготовьте данные о позициях меню<\\/p><p>Используя листы «Заказы» и «Меню и Товары», подготовьте таблицу, в которой для каждой позиции меню будут видны:<\\/p><p>Наименование;<\\/p><p>Общее количество проданных единиц.<\\/p><p>Для анализа продаж учитывайте только заказы со статусом «Доставлено».<\\/p><p>&nbsp;<\\/p><p>Задача 2. Определите самые популярные позиции<\\/p><p>На основании подготовленной таблицы, создайте новую таблицу, где будет только пять позиций меню с наибольшим количеством проданных единиц.<\\/p><p>Расположите позиции от наиболее популярной к менее популярной.<\\/p><p>&nbsp;<\\/p><p>Задача 3. Постройте столбчатую диаграмму популярных позиций<\\/p><p>На основании пяти выбранных позиций создайте столбчатую диаграмму.<\\/p><p>На горизонтальной оси должны находиться названия товаров.<\\/p><p>На вертикальной оси — количество проданных единиц.<\\/p><p>Настройте заголовок диаграммы так, чтобы было понятно, что она показывает.<\\/p><p>Проверьте, что подписи товаров читаются полностью или максимально понятно.<\\/p><p>&nbsp;<\\/p><p>Главная цель лабораторной работы — научиться самостоятельно проходить весь путь от исходных данных до понятного управленческого графика:<\\/p><p>данные → группировка → итоговый показатель → выбор подходящей диаграммы → настройка → вывод.<\\/p>\"}'),
(6, 4, '2.1. Создание Telegram-бота через BotFather и создание проекта в MaviBot.ai', 'botfather-and-mavibot', 1, '{\"theory\":\"<p>После работы с Google Таблицами переходим к следующему инструменту — MaviBot.ai.&nbsp;<br>В этом модуле мы будем создавать Telegram-бота для службы доставки.<\\/p><p>Чат-бот позволяет автоматизировать часть общения с клиентами.&nbsp;<\\/p><p>Вместо того чтобы сотрудник каждый раз вручную отвечал на одинаковые вопросы, бот может показать приветственное сообщение, предложить кнопки, запросить необходимые данные и направить пользователя по заранее подготовленному сценарию.<\\/p><p>&nbsp;<\\/p><p>В этом уроке мы создадим основу будущего бота:&nbsp;<br>зарегистрируемся в MaviBot.ai, создадим Telegram-бота через специальный официальный сервис BotFather, получим API-токен, подключим бота к проекту и проверим первое взаимодействие.<\\/p><p>&nbsp;<\\/p><p><strong>Мессенджеры и чат-боты<\\/strong><\\/p><p>Мессенджер — это приложение для обмена сообщениями между пользователями.&nbsp;<br>Telegram относится к популярным мессенджерам, но, кроме обычного общения между людьми, он позволяет создавать автоматизированных ботов.<\\/p><p>Telegram-бот — это специальный аккаунт, который может автоматически взаимодействовать с пользователем по заданным правилам.<\\/p><p>Например, бот службы доставки может:<\\/p><p>- принимать обращения клиентов;<\\/p><p>- показывать меню;<\\/p><p>- сообщать адрес доставки;<\\/p><p>- рассказывать о режиме работы;<\\/p><p>- принимать данные для заказа;<\\/p><p>- передавать информацию в другие сервисы.<\\/p><p>Сам Telegram предоставляет инфраструктуру для работы ботов, но логика поведения бота обычно настраивается отдельно.&nbsp;<\\/p><p>Для этого используются специальные платформы-конструкторы.<\\/p><p>В нашем курсе такой платформой будет MaviBot.ai.<\\/p><p>&nbsp;<\\/p><p>Получается следующая схема:<\\/p><p>Клиент → Telegram → Telegram-бот → MaviBot.ai → настроенный сценарий ответа<\\/p><p>Пользователь пишет сообщение боту в Telegram.&nbsp;<br>Telegram передаёт информацию боту, а подключённая платформа обрабатывает сценарий и определяет, что нужно ответить пользователю.<\\/p><p>На следующих уроках мы будем создавать более сложные сценарии.&nbsp;<\\/p><p>Сейчас важно понять базовый принцип:&nbsp;<br>Telegram-бот — это канал общения с пользователем, а MaviBot.ai используется для настройки логики его работы.<\\/p><p>&nbsp;<\\/p><p><strong>BotFather<\\/strong><\\/p><p>Создать обычный Telegram-аккаунт и превратить его в бота самостоятельно нельзя.&nbsp;<\\/p><p>Для управления Telegram-ботами используется официальный сервис BotFather.<\\/p><p>BotFather — это специальный бот Telegram, через который создаются и настраиваются другие боты.<\\/p><p>Через него можно:<\\/p><p>- создать нового бота;<\\/p><p>- задать ему имя;<\\/p><p>- получить уникальное имя пользователя;<\\/p><p>- получить API-токен;<\\/p><p>- изменять отдельные настройки созданного бота.<\\/p><p>&nbsp;<\\/p><p>Для начала Зайдите любым способом в свой аккаунт в Telegram.<\\/p><p>Проще всего на учебном компьютере зайти в web&nbsp;версию Telegram:<br>web.telegram.org<\\/p><p>На своём смартфоне откройте Telegram,<\\/p><p>далее: Настройки → Устройства → Подключить устройство.<\\/p><p>Далее, через QR-код войдите в свой аккаунт в web-версии Telegram.<\\/p><p>(в конце пары не забудьте выйти).<\\/p><p>В поиске наберите: BotFather<\\/p><p>Выберите только тот BotFather, который отмечен синей галочкой.<\\/p><p>Откройте чат с BotFather и отправьте команду:<\\/p><p><code>\\/start<\\/code><\\/p><p>или нажмите кнопку START.<\\/p><p>После этого BotFather покажет список доступных команд.<\\/p><p>Для создания нового бота используется команда:<\\/p><p><code>\\/newbot<\\/code><\\/p><p>BotFather попросит указать отображаемое имя бота.&nbsp;<\\/p><p>Это имя будут видеть пользователи.<\\/p><p>Например, для учебного проекта можно использовать простое название:<\\/p><p>Доставка<\\/p><p>После этого необходимо придумать username — техническое уникальное имя бота.&nbsp;<\\/p><p>Оно должно начинаться вашей фамилией и оканчиваться на bot.<br>Типа:<\\/p><p><code>&lt;Ваша_Фамилия&gt;_DeliveryBot<\\/code><\\/p><p>Например:<\\/p><p><code>Ivanov_DeliveryBot<\\/code><\\/p><p>&nbsp;<\\/p><p>Если выбранный вариант уже занят, Telegram попросит придумать другой.<\\/p><p>После успешного создания BotFather выдаст специальный API-токен.<\\/p><p>Типа:<br><code>8876301962:AABV_I5tFHu08o80E98pcsSxiF4nI9a31Fj<\\/code><\\/p><p>Сохраните API-токен в безопасном месте, например на своём Google-диске.<\\/p><p>В том же сообщении, где был API-токен, нажмите на ссылку на вашего бота, типа:&nbsp;<\\/p><p><code>t.me\\/Имя_вашего_бота<\\/code><\\/p><p>и нажмите кнопку Start.<\\/p><p>Созданный вами бот появится в списке чатов вашего Telegram.<\\/p><p>&nbsp;<\\/p><p><strong>Что такое API-токен<\\/strong><\\/p><p>API-токен — это секретный ключ, который используется для подтверждения права внешнего сервиса управлять конкретным Telegram-ботом.<\\/p><p>Упрощённо его можно представить как специальный пароль для подключения MaviBot.ai к вашему боту.<\\/p><p>Логика выглядит следующим образом:<\\/p><p>Telegram создаёт бота → BotFather выдаёт токен → токен передаётся в MaviBot.ai → MaviBot.ai получает возможность работать с этим ботом.<\\/p><p>API-токен является конфиденциальной информацией.<\\/p><p>Его нельзя:<\\/p><p>- публиковать в открытом доступе;<\\/p><p>- отправлять посторонним людям;<\\/p><p>- размещать в публичных документах;<\\/p><p>- показывать на скриншотах без необходимости.<\\/p><p>Если токен случайно стал доступен посторонним, его следует заменить через BotFather.<\\/p><p>Важно понимать: API-токен не является именем бота и не предназначен для обычного пользователя.&nbsp;<\\/p><p>Пользователь общается с ботом через Telegram, а токен используется технически для соединения Telegram с внешним сервисом.<\\/p><p>&nbsp;<\\/p><p><strong>Регистрация в MaviBot.ai и создание проекта для учебного бота<\\/strong><\\/p><p>Теперь необходимо создать аккаунт в MaviBot.ai.<\\/p><p>Откройте сервис mavibot.ai в браузере.<\\/p><p>&nbsp;<\\/p><p>(Интерфейс платформы может со временем изменяться, поэтому расположение отдельных кнопок и названия некоторых разделов могут отличаться.&nbsp;<\\/p><p>Однако общая логика работы остаётся одинаковой: сначала создаётся или открывается проект, затем подключается канал общения, после чего настраивается сценарий работы бота. Если что то будет не понятно в интерфейсе - обратитесь к преподавателю).<\\/p><p>&nbsp;<\\/p><p>В меню, справа вверху, переключитесь на русский язык.<\\/p><p>Нажмите кнопку \\\"Попробовать бесплатно\\\" (Get Started Free).<\\/p><p>Войдите через свой Google-аккаунт.<\\/p><p>Нажмите кнопку \\\"Настроить вручную\\\" (Set up manually).<\\/p><p>На странице настроек проекта - промотайте вниз.<\\/p><p>Введите название проекта \\\"Доставка\\\",<\\/p><p>справа внизу нажмите кнопку:&nbsp;<\\/p><p>\\\"Я&nbsp;хочу&nbsp;запустить&nbsp;проект&nbsp;самостоятельно\\\" (I want to set up the project myself).<\\/p><p>&nbsp;<\\/p><p>После создания проекта откроется рабочая область сервиса.<\\/p><p>&nbsp;<\\/p><p>На начальном этапе познакомьтесь с основными элементами интерфейса:<\\/p><p>Попробуйте переводить страницу на английский и русский язык, чтобы привыкнуть к обоим вариантам интерфейса.<\\/p><p>&nbsp;<\\/p><p>В левом вертикальном меню нажмите Каналы (Channels),<\\/p><p>выберите Telegram,<br>в окне Подключиться к Telegram (Connect Telegram) введите API токен,<\\/p><p>и нажмите: Подключить бота (Connect&nbsp;a&nbsp;bot).<\\/p><p>При успешном подключении - вы увидите имя своего бота.&nbsp;<\\/p><p>&nbsp;<\\/p><p>Таким образом, создаётся связь:<\\/p><p>Telegram-бот → API-токен → MaviBot.ai → проект бота<\\/p><p>На этом этапе ещё не требуется создавать сложный сценарий.&nbsp;<br>Главная цель — убедиться, что платформа получила доступ к созданному Telegram-боту.<\\/p><p>&nbsp;<\\/p><p>Проект можно представить как рабочее пространство, внутри которого будет находиться логика будущего чат-бота.<\\/p><p>В следующих уроках в этом же проекте мы будем:<\\/p><p>- создавать приветственное сообщение;<\\/p><p>- добавлять кнопки;<\\/p><p>- строить ветки диалога;<\\/p><p>- запрашивать данные клиента;<\\/p><p>- передавать информацию в Google Таблицы.<\\/p><p>Поэтому сейчас важно сохранить созданный проект и не удалять подключение после завершения урока.<\\/p><p>&nbsp;<\\/p><p>Не нужно пытаться сразу настроить все возможности платформы.&nbsp;<\\/p><p>В этом уроке главная задача — создать рабочее подключение Telegram-бота.<\\/p><p>&nbsp;<\\/p><p><strong>Первое тестовое взаимодействие<\\/strong><\\/p><p>После подключения откройте Telegram и найдите своего созданного бота.<\\/p><p>Откройте диалог с ним.<\\/p><p>Если вы ещё не запускали бота, нажмите кнопку Start или отправьте команду:<\\/p><p><code>\\/start<\\/code><\\/p><p>Если вы не видите бота воспользуйтесь стандартным поиском Telegram, введя техническое имя бота.<\\/p><p>&nbsp;<\\/p><p>После этого отправьте простое тестовое сообщение.<\\/p><p><code>Тест<\\/code><\\/p><p>Ответа вы не получите, т.к. никакая логика ещё не создан, но две зелёные галочки означают, что сообщения уходят.<\\/p><p>Полноценную логику диалога и кнопочное меню будем создавать в следующем уроке.<\\/p><p>&nbsp;<\\/p><p><strong>Типичные ошибки начинающих<\\/strong><\\/p><p>Одна из распространённых ошибок — путать BotFather и созданного бота.<\\/p><p>BotFather нужен для создания и технического управления ботами.&nbsp;<\\/p><p>Пользователь службы доставки будет общаться не с BotFather, а с ботом, которого вы создали через него.<\\/p><p>Другая ошибка — путать имя бота и API-токен.<\\/p><p>Имя используется для отображения пользователю.<\\/p><p>Username используется для уникального поиска бота в Telegram.<\\/p><p>API-токен используется для технического подключения внешнего сервиса.<\\/p><p>Ещё одна распространённая проблема — вставка неправильного или неполного токена в MaviBot.ai.&nbsp;<\\/p><p>В этом случае сервис не сможет подключиться к Telegram.<\\/p><p>Также не следует публиковать токен в учебных чатах или открытых документах.&nbsp;<\\/p><p>Если секретный ключ стал доступен посторонним, его необходимо заменить.<\\/p><p>&nbsp;<\\/p><p>Важно помнить и общую последовательность работы:<\\/p><p>- сначала создаётся бот в Telegram через BotFather;<\\/p><p>- затем получается API-токен;<\\/p><p>- после этого токен используется для подключения бота к MaviBot.ai;<\\/p><p>- затем проверяется первое взаимодействие.<\\/p><p>&nbsp;<\\/p><p><strong>Что нужно запомнить<\\/strong><\\/p><p>Telegram-бот — это специальный аккаунт для автоматизированного взаимодействия с пользователями.<\\/p><p>BotFather используется для создания и управления Telegram-ботами.<\\/p><p>При создании бота BotFather выдаёт API-токен.<\\/p><p>API-токен нужен для подключения Telegram-бота к внешней платформе и является конфиденциальной информацией.<\\/p><p>MaviBot.ai используется для настройки логики и сценариев работы бота.<\\/p><p>После подключения необходимо провести тестирование и убедиться, что используется правильный Telegram-бот.<\\/p><p>&nbsp;<\\/p><p>В следующем уроке мы начнём создавать сам сценарий общения: настроим приветственное сообщение, кнопки главного меню и отдельные ветки диалога.<\\/p>\",\"tests\":[{\"question\":\"Какое основное назначение Telegram-бота?\",\"answers\":[\"Автоматически взаимодействовать с пользователями по настроенному сценарию ✓\",\"Заменять приложение Telegram на компьютере\",\"Создавать новые аккаунты пользователей\",\"Хранить все файлы пользователя без ограничений\"],\"correct\":null},{\"question\":\"Какой сервис Telegram используется для создания новых ботов?\",\"answers\":[\"Telegram Desktop\",\"BotFather ✓\",\"NewBot\",\"MaviBot.ai\"],\"correct\":null},{\"question\":\"Что такое API-токен Telegram-бота?\",\"answers\":[\"Отображаемое название бота\",\"Секретный ключ для подключения и управления ботом через сервисы ✓\",\"Первое сообщение Telegram-боту для запуска диалога с ботом\",\"Название группы, в которой работает бот\"],\"correct\":null},{\"question\":\"Почему API-токен нельзя публиковать в открытом доступе?\",\"answers\":[\"Он автоматически удаляет Telegram-аккаунт\",\"После публикации ваши данные автоматически передаются в органы\",\"После публикации бот перестаёт принимать сообщения навсегда\",\"Он содержит секретные данные для доступа к управлению ботом ✓\"],\"correct\":null},{\"question\":\"В какой последовательности обычно выполняется первоначальная настройка?\",\"answers\":[\"Создание сценария → удаление Telegram → регистрация пользователя\",\"Регистрация в Google Таблицах → создание канала → удаление токена\",\"Создание бота через BotFather → получение токена → подключение к MaviBot.ai ✓\",\"Создание кнопок → публикация токена → создание BotFather\"],\"correct\":null},{\"question\":\"Что следует сделать, если API-токен случайно стал доступен посторонним?\",\"answers\":[\"Такого произойти не может\",\"Удалить Telegram с устройства, потом установить заново и создать новый Telegram-аккаунт\",\"Заменить или отозвать скомпрометированный токен через средства управления ботом ✓\",\"Создать новый Google-аккаунт\"],\"correct\":null}],\"lab\":\"<p>В этой лабораторной работе проделайте всю описанную в уроке последовательность действий самостоятельно заново.<\\/p><p>Удалите созданный в урокеTelegram-бот.<\\/p><p>Проделайте весь алгоритм создания бота заново.<\\/p><p>Удалите проект и аккаунт MaviBot.ai.<\\/p><p>Проделайте всю процедуру регистрации и создания проекта для работы с ботом заново.<\\/p><p>Желательно сделать это с другого Google-аккаунта.<\\/p><p>&nbsp;<\\/p><p>Сформулируйте для себя ответ на главный вопрос урока: какую задачу выполняет каждый элемент этой цепочки?<\\/p><p>BotFather создаёт и управляет Telegram-ботом.<\\/p><p>API-токен подтверждает возможность технического подключения.<\\/p><p>MaviBot.ai настраивает логику работы бота.<\\/p><p>Telegram используется пользователем как канал общения с ботом.<\\/p>\"}');

